static void testNoteChase(const File& root,Assets& assets){
    auto source=emptyProject();source.bpm=120;source.loop=false;source.tracks[7].instrument=Instrument::analog;source.tracks[7].volume=.35f;source.tracks[7].send=0;source.tracks[7].attack=.001f;source.tracks[7].release=.02f;source.tracks[7].synth.wave1=0;source.tracks[7].synth.wave2=0;source.tracks[7].synth.sub=0;source.tracks[7].synth.noise=0;source.tracks[7].synth.mix=0;source.tracks[7].synth.decay=.01f;source.tracks[7].synth.sustain=1;source.patterns[0].lanes[7]={{0,4,60,.8f}};
    AudioBuffer<float> a(2,24000),b(2,24000);auto engine=makeEngine(source,assets,root);engine->seekRequested.store(2);engine->render(a.getWritePointer(0),a.getWritePointer(1),24000);
    expect(engine->chasedNotes.load()==1&&a.getMagnitude(0,0,24000)>.01f,"seeking inside a held synth gate restores audible notes immediately");engine->render(a.getWritePointer(0),a.getWritePointer(1),24000);engine->render(a.getWritePointer(0),a.getWritePointer(1),24000);expect(a.getMagnitude(0,18000,6000)<.00001f,"chased notes end at their original gate endpoint, not a fresh full duration");
    engine=makeEngine(source,assets,root);engine->playing.store(false);engine->seekRequested.store(2);engine->render(a.getWritePointer(0),a.getWritePointer(1),2048);expect(a.getMagnitude(0,0,2048)==0&&engine->chasedNotes.load()==0,"seeking while paused stays silent and defers note chase");engine->start();engine->render(a.getWritePointer(0),a.getWritePointer(1),2048);expect(a.getMagnitude(0,0,2048)>.01f&&engine->chasedNotes.load()==1,"Play after a paused seek chases the held gate");
    source.patterns[0].lanes[7][0].beat=1;auto atOnset=makeEngine(source,assets,root);atOnset->seekRequested.store(1);atOnset->render(a.getWritePointer(0),a.getWritePointer(1),2048);auto reference=source;reference.patterns[0].lanes[7][0].beat=0;auto normal=makeEngine(reference,assets,root);normal->render(b.getWritePointer(0),b.getWritePointer(1),2048);float difference=0;for(int ch=0;ch<2;++ch)for(int i=0;i<2048;++i)difference=jmax(difference,std::abs(a.getSample(ch,i)-b.getSample(ch,i)));expect(atOnset->chasedNotes.load()==0&&difference<.000001f,"seeking exactly to an onset triggers it once through normal scheduling");
    source.patterns[0].lanes[7][0].beat=1-.0000005;atOnset=makeEngine(source,assets,root);atOnset->seekRequested.store(1);atOnset->render(a.getWritePointer(0),a.getWritePointer(1),2048);expect(atOnset->chasedNotes.load()==0,"near-onset chase tolerance agrees with normal scheduling to avoid double notes");
    source=reference;engine=makeEngine(source,assets,root);engine->seekRequested.store(4);engine->render(a.getWritePointer(0),a.getWritePointer(1),2048);expect(a.getMagnitude(0,0,2048)==0&&engine->chasedNotes.load()==0,"a gate ending at the seek point is not restarted as a tail");
    for(int mode=0;mode<3;++mode){auto skipped=source;if(mode==0)skipped.tracks[7].instrument=Instrument::kick;if(mode==1)skipped.tracks[7].mute=true;if(mode==2)skipped.patterns[0].lanes[7][0].probability=0;engine=makeEngine(skipped,assets,root);engine->seekRequested.store(1);engine->render(a.getWritePointer(0),a.getWritePointer(1),2048);expect(a.getMagnitude(0,0,2048)==0&&engine->chasedNotes.load()==0,"chase excludes drums, muted notes and rejected probability events");}
    auto probabilistic=source;probabilistic.patterns[0].lanes[7].clear();for(int i=0;i<12;++i)probabilistic.patterns[0].lanes[7].push_back({0,4,48+i,.4f,.37f});auto chased=makeEngine(probabilistic,assets,root);normal=makeEngine(probabilistic,assets,root);chased->seekRequested.store(1);chased->render(a.getWritePointer(0),a.getWritePointer(1),2048);normal->render(b.getWritePointer(0),b.getWritePointer(1),2048);difference=0;for(int ch=0;ch<2;++ch)for(int i=0;i<2048;++i)difference=jmax(difference,std::abs(a.getSample(ch,i)-b.getSample(ch,i)));expect(chased->chasedNotes.load()>0&&chased->chasedNotes.load()<12&&difference<.000001f,"chase uses the same deterministic probability choices as the original onsets");
    auto ratcheted=source;ratcheted.patterns[0].lanes[7][0].ratchets=4;engine=makeEngine(ratcheted,assets,root);engine->seekRequested.store(1.5);engine->render(a.getWritePointer(0),a.getWritePointer(1),2048);expect(engine->chasedNotes.load()==1&&a.getMagnitude(0,0,2048)>.01f,"chase restores only the currently held ratchet sub-gate");
    auto held=source;held.patterns[0].length=64;held.patterns[0].lanes[7][0].length=64;engine=makeEngine(held,assets,root);normal=makeEngine(held,assets,root);engine->render(a.getWritePointer(0),a.getWritePointer(1),2048);normal->render(b.getWritePointer(0),b.getWritePointer(1),2048);for(int i=0;i<20;++i){engine->playing.store(false);engine->render(a.getWritePointer(0),a.getWritePointer(1),2048);normal->render(b.getWritePointer(0),b.getWritePointer(1),2048);engine->start();engine->render(a.getWritePointer(0),a.getWritePointer(1),2048);normal->render(b.getWritePointer(0),b.getWritePointer(1),2048);}difference=0;for(int ch=0;ch<2;++ch)for(int i=0;i<2048;++i)difference=jmax(difference,std::abs(a.getSample(ch,i)-b.getSample(ch,i)));if(engine->chasedNotes.load()!=20||difference>.000001f)std::cerr<<"Resume diagnostics: chased="<<engine->chasedNotes.load()<<", waveform difference="<<difference<<"\n";expect(engine->chasedNotes.load()==20&&difference<.000001f,"repeated pause/resume reuses held voices instead of accumulating duplicate gain");
    auto count=engine->chasedNotes.load();auto adjusted=held;adjusted.tracks[7].volume=.3f;String warning;expect(compilePlayback(adjusted,assets,root,engine->exchange.beginWrite(),warning).wasOk(),"compile a normal live fader edit");engine->exchange.publish();engine->render(a.getWritePointer(0),a.getWritePointer(1),2048);expect(engine->chasedNotes.load()==count,"ordinary live parameter publication does not retrigger held notes");
    auto looped=source;looped.songMode=true;looped.loop=true;looped.patterns[0].lanes[7][0].length=8;looped.clips={{7,0,0,8}};looped.markers={{"held-section","Held section",2,3,0}};looped.loopSection="held-section";engine=makeEngine(looped,assets,root);for(int i=0;i<6;++i)engine->render(a.getWritePointer(0),a.getWritePointer(1),12000);expect(engine->completedLoops.load()>=3&&engine->chasedNotes.load()>=3&&a.getRMSLevel(0,0,12000)>.01f,"section loops chase notes beginning before the section and retain sustained audio across wraps");
    auto blockwise=makeEngine(source,assets,root);auto whole=makeEngine(source,assets,root);blockwise->seekRequested.store(1.25);whole->seekRequested.store(1.25);whole->render(a.getWritePointer(0),a.getWritePointer(1),24000);for(int i=0;i<24000;i+=127){int n=jmin(127,24000-i);blockwise->render(b.getWritePointer(0,i),b.getWritePointer(1,i),n);}difference=0;for(int ch=0;ch<2;++ch)for(int i=0;i<24000;++i)difference=jmax(difference,std::abs(a.getSample(ch,i)-b.getSample(ch,i)));expect(difference==0,"chased audio and gate timing are independent of callback block size");
    auto sampleFile=root.getChildFile("chase-sample.wav");{TemporaryFile temp(sampleFile);std::unique_ptr<OutputStream> output(temp.getFile().createOutputStream());auto writer=WavAudioFormat().createWriterFor(output,AudioFormatWriterOptions{}.withSampleRate(48000).withNumChannels(2).withBitsPerSample(24));AudioBuffer<float> sample(2,48000);for(int i=0;i<48000;++i){sample.setSample(0,i,.2f+i/240000.f);sample.setSample(1,i,-.1f-i/480000.f);}expect(writer&&writer->writeFromAudioSampleBuffer(sample,0,48000),"write stereo sampler chase fixture");writer.reset();expect(temp.overwriteTargetFileWithTemporary(),"commit stereo chase sample fixture");}
    auto sampler=source;sampler.tracks[7].instrument=Instrument::sample;sampler.tracks[7].samplePath=sampleFile.getFullPathName();sampler.tracks[7].sampleStart=.1;sampler.tracks[7].sampleEnd=.6;sampler.patterns[0].lanes[7][0].pitch=72;engine=makeEngine(sampler,assets,root);engine->seekRequested.store(.25);engine->render(a.getWritePointer(0),a.getWritePointer(1),2048);auto offset=sampler;offset.tracks[7].sampleStart=.35;normal=makeEngine(offset,assets,root);normal->render(b.getWritePointer(0),b.getWritePointer(1),2048);difference=0;for(int ch=0;ch<2;++ch)for(int i=0;i<2048;++i)difference=jmax(difference,std::abs(a.getSample(ch,i)-b.getSample(ch,i)));expect(engine->chasedNotes.load()==1&&difference<.00001f,"sampler chase honors source range, stereo channels and pitch-dependent source position");
    engine=makeEngine(sampler,assets,root);engine->seekRequested.store(1);engine->render(a.getWritePointer(0),a.getWritePointer(1),2048);expect(engine->chasedNotes.load()==0&&a.getMagnitude(0,0,2048)==0,"exhausted one-shot samples are not restarted merely because a note gate remains");sampler.tracks[7].sampleLoop=true;engine=makeEngine(sampler,assets,root);engine->seekRequested.store(1.25);engine->render(a.getWritePointer(0),a.getWritePointer(1),2048);normal=makeEngine(offset,assets,root);normal->render(b.getWritePointer(0),b.getWritePointer(1),2048);difference=0;for(int ch=0;ch<2;++ch)for(int i=0;i<2048;++i)difference=jmax(difference,std::abs(a.getSample(ch,i)-b.getSample(ch,i)));expect(engine->chasedNotes.load()==1&&difference<.00001f,"looped sampler chase wraps source offsets within the selected range");
    auto dense=source;while(dense.tracks.size()<maxTracks)dense.tracks.push_back(dense.tracks[7]);dense.patterns[0].length=64;dense.patterns[0].lanes.resize(maxTracks);for(auto& t:dense.tracks)t=dense.tracks[7];for(auto& lane:dense.patterns[0].lanes)lane.assign(512,Note{0,64,60,.1f,1,4});engine=makeEngine(dense,assets,root);engine->seekRequested.store(8);engine->render(a.getWritePointer(0),a.getWritePointer(1),128);bool finite=true;for(int ch=0;ch<2;++ch)for(int i=0;i<128;++i)finite&=std::isfinite(a.getSample(ch,i));expect(engine->chasedNotes.load()==128&&finite,"maximum-event chase is capped to the fixed 128-voice budget without invalid audio");
}
